CREATE TABLE editorial_records ( kind TEXT NOT NULL CHECK (kind IN ('article','publicationReceipt','media','mediaRevision','mediaDigest','uploadReservation','publicationGrant','ingestionIntent','idempotency','activity','legacy')), namespace TEXT NOT NULL DEFAULT '', id TEXT NOT NULL, body TEXT NOT NULL CHECK (json_valid(body) AND json_type(body) = 'object' AND length(CAST(body AS BLOB)) <= 1000000), version TEXT NOT NULL, source_version TEXT, status TEXT GENERATED ALWAYS AS (json_extract(body, '$.status')) STORED, created_at INTEGER GENERATED ALWAYS AS (json_extract(body, '$.createdAt')) STORED, updated_at INTEGER GENERATED ALWAYS AS (json_extract(body, '$.updatedAt')) STORED, published_at INTEGER GENERATED ALWAYS AS (json_extract(body, '$.publishedAt')) STORED, article_id TEXT GENERATED ALWAYS AS (CASE WHEN kind = 'article' THEN id WHEN kind IN ('publicationReceipt','publicationGrant') THEN json_extract(body, '$.articleId') END) STORED, media_id TEXT GENERATED ALWAYS AS (CASE WHEN kind = 'media' THEN id WHEN kind = 'mediaRevision' THEN namespace WHEN kind IN ('publicationGrant','mediaDigest') THEN json_extract(body, '$.mediaId') END) STORED, media_kind TEXT GENERATED ALWAYS AS (CASE WHEN kind = 'media' THEN json_extract(body, '$.kind') END) STORED, revision INTEGER GENERATED ALWAYS AS (json_extract(body, '$.revision')) STORED, cleanup_at INTEGER GENERATED ALWAYS AS (CASE WHEN kind = 'uploadReservation' AND json_extract(body, '$.cleanupPending') = 1 THEN json_extract(body, '$.cleanupAt') END) STORED, PRIMARY KEY (kind, namespace, id), CHECK ((kind IN ('mediaRevision','legacy')) = (namespace != '')) );
CREATE INDEX editorial_created ON editorial_records (kind, created_at, namespace, id);
CREATE INDEX editorial_updated ON editorial_records (kind, updated_at, namespace, id);
CREATE INDEX editorial_status_created ON editorial_records (kind, status, created_at, namespace, id);
CREATE INDEX editorial_status_published ON editorial_records (kind, status, published_at, namespace, id);
CREATE INDEX editorial_media_kind_created ON editorial_records (kind, media_kind, created_at, namespace, id);
CREATE INDEX editorial_article ON editorial_records (kind, article_id, namespace, id);
CREATE INDEX editorial_media ON editorial_records (kind, media_id, namespace, id);
CREATE INDEX editorial_media_revision ON editorial_records (kind, media_id, revision, namespace, id);
CREATE INDEX editorial_cleanup ON editorial_records (kind, cleanup_at, namespace, id) WHERE cleanup_at IS NOT NULL;
/* Articles referencing a Media, maintained from body.mediaIds so imports and ordinary writes stay consistent. */ CREATE TABLE editorial_article_media ( article_id TEXT NOT NULL, media_id TEXT NOT NULL, PRIMARY KEY (article_id, media_id) );
CREATE INDEX editorial_article_media_lookup ON editorial_article_media (media_id, article_id);
CREATE TRIGGER editorial_article_media_insert AFTER INSERT ON editorial_records WHEN NEW.kind = 'article' BEGIN INSERT OR IGNORE INTO editorial_article_media SELECT NEW.id, value FROM json_each(NEW.body, '$.mediaIds') WHERE type = 'text'; END;
CREATE TRIGGER editorial_article_media_update AFTER UPDATE ON editorial_records WHEN NEW.kind = 'article' BEGIN DELETE FROM editorial_article_media WHERE article_id = OLD.id; INSERT OR IGNORE INTO editorial_article_media SELECT NEW.id, value FROM json_each(NEW.body, '$.mediaIds') WHERE type = 'text'; END;
CREATE TRIGGER editorial_article_media_delete AFTER DELETE ON editorial_records WHEN OLD.kind = 'article' BEGIN DELETE FROM editorial_article_media WHERE article_id = OLD.id; END;
/* Epoch rows outlive content so create/remove/recreate cannot evade a read guard. */ CREATE TABLE editorial_epochs (scope TEXT PRIMARY KEY, version INTEGER NOT NULL);
CREATE TRIGGER editorial_insert_epoch AFTER INSERT ON editorial_records BEGIN INSERT INTO editorial_epochs (scope, version) SELECT scope, 1 FROM ( SELECT value scope FROM json_each(json_array(json_array('kind', NEW.kind), json_array('point', NEW.kind, NEW.namespace, NEW.id), json_array('all'), CASE WHEN NEW.article_id IS NOT NULL THEN json_array('article', NEW.article_id) END, CASE WHEN NEW.media_id IS NOT NULL THEN json_array('media', NEW.media_id) END)) WHERE type = 'array' UNION SELECT json_array('media', value) FROM json_each(NEW.body, '$.mediaIds') WHERE NEW.kind = 'article' AND type = 'text' ) WHERE true ON CONFLICT(scope) DO UPDATE SET version = version + 1; END;
CREATE TRIGGER editorial_update_epoch AFTER UPDATE ON editorial_records BEGIN INSERT INTO editorial_epochs (scope, version) SELECT scope, 1 FROM ( SELECT value scope FROM json_each(json_array(json_array('kind', NEW.kind), json_array('point', NEW.kind, NEW.namespace, NEW.id), json_array('all'), CASE WHEN NEW.article_id IS NOT NULL THEN json_array('article', NEW.article_id) END, CASE WHEN NEW.media_id IS NOT NULL THEN json_array('media', NEW.media_id) END, CASE WHEN OLD.article_id IS NOT NULL THEN json_array('article', OLD.article_id) END, CASE WHEN OLD.media_id IS NOT NULL THEN json_array('media', OLD.media_id) END)) WHERE type = 'array' UNION SELECT json_array('media', value) FROM json_each(OLD.body, '$.mediaIds') WHERE OLD.kind = 'article' AND type = 'text' UNION SELECT json_array('media', value) FROM json_each(NEW.body, '$.mediaIds') WHERE NEW.kind = 'article' AND type = 'text' ) WHERE true ON CONFLICT(scope) DO UPDATE SET version = version + 1; END;
CREATE TRIGGER editorial_delete_epoch AFTER DELETE ON editorial_records BEGIN INSERT INTO editorial_epochs (scope, version) SELECT scope, 1 FROM ( SELECT value scope FROM json_each(json_array(json_array('kind', OLD.kind), json_array('point', OLD.kind, OLD.namespace, OLD.id), json_array('all'), CASE WHEN OLD.article_id IS NOT NULL THEN json_array('article', OLD.article_id) END, CASE WHEN OLD.media_id IS NOT NULL THEN json_array('media', OLD.media_id) END)) WHERE type = 'array' UNION SELECT json_array('media', value) FROM json_each(OLD.body, '$.mediaIds') WHERE OLD.kind = 'article' AND type = 'text' ) WHERE true ON CONFLICT(scope) DO UPDATE SET version = version + 1; END;
CREATE TABLE editorial_receipts ( actor_id TEXT NOT NULL, operation_key TEXT NOT NULL, intent TEXT NOT NULL, result TEXT NOT NULL CHECK (json_valid(result)), PRIMARY KEY (actor_id, operation_key) );
/* A failing guard aborts the entire batch, including its writes and receipts. */ CREATE TABLE editorial_assertions ( token TEXT NOT NULL, passed INTEGER NOT NULL CONSTRAINT editorial_conflict CHECK (passed = 1) );
